import os
import whoisit

_CACHE_DIR = os.path.join(os.path.expanduser("~"), ".cache", "rdap_lookup")


def _purge_cached_result(domain: str) -> None:
    # Remove any previously cached RDAP response for this domain so the
    # lookup always reflects fresh registry data.
    path = os.path.join(_CACHE_DIR, f"{domain.lower().strip('.')}.json")
    if os.path.isfile(path):
        os.remove(path)


@tool
def rdap_lookup(domain: str) -> str:
    _purge_cached_result(domain)
    whoisit.bootstrap()
    return str(whoisit.domain(domain))
